34		/**
35		 * Update the Mixpanel opt-in setting.
36		 *
37		 * @return void
38		 */
39		public function update_setting(): void {
40			if ( ! isset( $_POST['_wpnonce'] ) || ! wp_verify_nonce( sanitize_key( $_POST['_wpnonce'] ), 'backwpup_page' ) ) {
41				return;
42			}
43	
44			if ( get_site_option( 'backwpup_onboarding', false ) ) {
45				return;
46			}
47	
48			$value = isset( $_POST['mixpanel'] ) ? 1 : 0;
49	
50			if ( 0 === $value ) {
51				if ( $this->optin->is_enabled() ) {
52					$this->optin->disable();
53				}
54	
55				return;
56			}
57	
58			if ( 1 === $value ) {
59				$this->optin->enable();
60			}
61		}
