181		/**
182		 * Track end of job.
183		 *
184		 * @param int    $job_id The job id.
185		 * @param array  $job_details The status of the job.
186		 * @param string $trigger Backup trigger.
187		 *
188		 * @return void
189		 */
190		public function track_end_job( $job_id, array $job_details, $trigger ): void {
191			if ( ! $this->optin->can_track() ) {
192				return;
193			}
194	
195			$job   = $this->option_adapter->get_job( $job_id );
196			$user  = wp_get_current_user();
197			$email = $user->user_email ?? $job['mailaddresslog'];
198	
199			$this->mixpanel->identify( $email );
200			$status = true;
201	
202			$properties                   = array_merge( $this->get_default_event_properties(), $this->get_backup_event_properties( $job, true ) );
203			$properties['backup_trigger'] = $trigger;
204	
205			foreach ( $job_details as $job ) {
206				$properties[ 'storage_' . $job['storage'] ] = [
207					'storage'       => $job['storage'],
208					'status'        => $job['status'],
209					'error_code'    => $job['error_code'],
210					'error_message' => $job['error_message'],
211				];
212	
213				if ( 'completed' !== $job['status'] ) {
214					$status = false;
215				}
216			}
217	
218			$properties['job_completed'] = $status;
219	
220			// @todo Refactor it when the Mixpanel library supports system capabilities.
221			$this->with_system_cap(
222					function () use ( $properties ) {
223						$this->mixpanel->track(
224						'Scheduled Backup Job Ended',
225						$properties,
226						'bwu_mixpanel_send_event'
227						);
228					}
229				);
230		}
