232		/**
233		 * Get backup event properties.
234		 *
235		 * @param array $job The job data.
236		 * @param bool  $included_job_completion Include job completion info.
237		 *
238		 * @return array
239		 */
240		private function get_backup_event_properties( array $job, bool $included_job_completion = false ): array {
241			$legacy_job = ! empty( $job['legacy'] );
242	
243			$properties = [
244				'legacy_job' => $legacy_job,
245			];
246	
247			if ( $included_job_completion ) {
248				$properties['duration'] = $job['lastruntime'];
249			}
250	
251			return array_merge( $this->get_event_properties( $job, false ), $properties );
252		}
