254		/**
255		 * Get the properties for the event.
256		 *
257		 * @param array $job The job data.
258		 * @param bool  $exclude_scheduled_info Exclude some scheduled info.
259		 *
260		 * @return array
261		 */
262		private function get_event_properties( array $job, bool $exclude_scheduled_info = false ): array {
263			if ( empty( $job['archiveformat'] ) ) {
264				$job['archiveformat'] = get_site_option( 'backwpup_archiveformat', '.tar' );
265			}
266	
267			$properties = [
268				'job_id'                 => $job['jobid'],
269				'storage'                => $job['destinations'],
270				'format'                 => $job['archiveformat'],
271				'manually_excluded_data' => $this->has_manual_exclude( $job ),
272			];
273	
274			if ( ! $exclude_scheduled_info ) {
275				$properties['frequency'] = $job['frequency'];
276				$properties['type']      = $job['type'];
277			}
278	
279			return $properties;
280		}
