private function get_backup_trigger( string $start_type, array $job ): string {
	$trigger = 'first_job';
	switch ( $start_type ) {
		case 'runcli':
			$trigger = 'wp-cli';
			break;
		case 'cronrun':
			$trigger = 'scheduled_job';
			break;
		case 'runext':
			$trigger = 'link';
			break;
		case 'runnow':
			$trigger = 'backup_now_job';
			if ( ! empty( $job['backup_now'] ) ) {
				$trigger = 'backup_now_global';
			} elseif ( $job['tempjob'] ) {
				$trigger = 'first_job';
			}
			break;
	}

	return $trigger;
}

