/**
 * execute() returns backwpup_invalid_job_id error when the provided job ID does not exist.
 */
public function test_execute_returns_error_for_invalid_job_id() {
	$this->job_adapter->shouldReceive( 'get_working_data' )->andReturn( null );
	$this->option_adapter->shouldReceive( 'get_job' )->with( 99999 )->andReturn( false );

	$result = $this->ability->execute( [ 'job_id' => 99999 ] );

	$this->assertInstanceOf( \WP_Error::class, $result );
	$this->assertEquals( 'backwpup_invalid_job_id', $result->get_error_code() );
}

